import { StatusPill } from './StatusPill';

interface TeamLobbyProps {
  team: Team;
  runners: Runner[];
  missions: Mission[];
}

export function TeamLobby({ team, runners, missions }: TeamLobbyProps) {
  const missionById = new Map(missions.map((mission) => [mission.id, mission]));

  return (
    <section className="panel team-panel" aria-labelledby="team-lobby-title">
      <div className="section-heading">
        <div>
          <p className="eyebrow">Team lobby · {team.callSign}</p>
          <h2 id="team-lobby-title">Runners on the web</h2>
        </div>
        <span className="count-badge">{runners.length}</span>
      </div>

      {runners.length === 0 ? (
        <div className="empty-state compact-empty">
          <span className="empty-glyph" aria-hidden="true">○</span>
          <h3>No runners connected</h3>
          <p>Connect an Entire-enabled session to populate the team lobby.</p>
        </div>
      ) : (
        <div className="runner-grid">
          {runners.map((runner) => {
            const mission = runner.currentMissionId ? missionById.get(runner.currentMissionId) : undefined;
            return (
              <article className="runner-card" key={runner.id} style={{ '--runner-accent': runner.accent } as React.CSSProperties}>
                <div className="runner-identity">
                  <span className="runner-avatar" aria-hidden="true">{runner.initials}</span>
                  <div>
                    <h3>{runner.displayName}</h3>
                    <p>{runner.archetype}</p>
                  </div>
                  <StatusPill status={runner.status} />
                </div>
                <p className="runner-role">{runner.role}</p>
                <div className="runner-meta">
                  <span>{runner.provider}</span>
                  <span>{mission?.title ?? 'Awaiting assignment'}</span>
                </div>
              </article>
            );
          })}
        </div>
      )}
    </section>
  );
}

import type { GitSnapshot, GraphSnapshot, ProviderHealth } from '../domain';
import { StatusPill } from './StatusPill';

interface ProviderPanelProps {
  providers: ProviderHealth[];
}

export function ProviderPanel({ providers }: ProviderPanelProps) {
  return (
    <section className="panel provider-panel" aria-labelledby="provider-health-title">
      <div className="section-heading">
        <div>
          <p className="eyebrow">Signal network</p>
          <h2 id="provider-health-title">Provider health</h2>
        </div>
      </div>
      {providers.length === 0 ? (
        <p className="muted-copy">No providers configured.</p>
      ) : (
        <ul className="provider-list">
          {providers.map((provider) => (
            <li key={provider.id}>
              <span className="provider-pulse" aria-hidden="true" />
              <div>
                <strong>{provider.name}</strong>
                <span>{provider.detail}</span>
              </div>
              <div className="provider-status">
                <StatusPill status={provider.status} />
                <small>{provider.latencyMs ? `${provider.latencyMs}ms · ` : ''}{provider.lastCheckedAt}</small>
              </div>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

interface GitPanelProps {
  git: GitSnapshot;
}

export function GitPanel({ git }: GitPanelProps) {
  return (
    <section className="panel git-panel" aria-labelledby="git-activity-title">
      <div className="section-heading">
        <div>
          <p className="eyebrow">Source control</p>
          <h2 id="git-activity-title">Git activity</h2>
        </div>
        <code>{git.branch}</code>
      </div>
      <div className="git-summary">
        <span>HEAD <strong>{git.head}</strong></span>
        <span>{git.dirtyFileCount} dirty</span>
        <span>↑{git.ahead} ↓{git.behind}</span>
      </div>
      {git.activity.length === 0 ? (
        <p className="muted-copy">No recent Git activity.</p>
      ) : (
        <ol className="activity-list">
          {git.activity.map((item) => (
            <li key={item.id}>
              <span className="timeline-dot" aria-hidden="true" />
              <div>
                <strong>{item.action}</strong>
                <span>{item.actor} · <code>{item.ref}</code> · {item.timestamp}</span>
              </div>
            </li>
          ))}
        </ol>
      )}
    </section>
  );
}

interface GraphPanelProps {
  graph: GraphSnapshot;
}

export function GraphPanel({ graph }: GraphPanelProps) {
  return (
    <section className="panel graph-panel" aria-labelledby="graph-integrity-title">
      <div className="section-heading">
        <div>
          <p className="eyebrow">Structural scan</p>
          <h2 id="graph-integrity-title">Graph integrity</h2>
        </div>
        <span className={`graph-completeness ${graph.complete ? 'complete' : 'partial'}`}>
          {graph.complete ? 'Complete' : 'Partial'}
        </span>
      </div>
      <div className="metric-grid">
        <div><strong>{graph.nodeCount.toLocaleString()}</strong><span>Nodes</span></div>
        <div><strong>{graph.relationCount.toLocaleString()}</strong><span>Relations</span></div>
        <div><strong>{graph.analyzedDepth}</strong><span>Depth</span></div>
      </div>
      {graph.warning ? <p className="graph-warning">{graph.warning}</p> : null}
    </section>
  );
}

import type { RiskSignal } from '../domain';
import { StatusPill } from './StatusPill';

interface RiskConsoleProps {
  risks: RiskSignal[];
  selectedRiskId?: string;
  onSelectRisk: (riskId: string) => void;
}

export function RiskConsole({ risks, selectedRiskId, onSelectRisk }: RiskConsoleProps) {
  const actionable = risks.filter((risk) => risk.level !== 'CLEAR');

  return (
    <section className="panel risk-panel" aria-labelledby="risk-console-title">
      <div className="section-heading">
        <div>
          <p className="eyebrow">Early warning</p>
          <h2 id="risk-console-title">Risk signals</h2>
        </div>
        <span className="count-badge danger-count">{actionable.length}</span>
      </div>

      {risks.length === 0 ? (
        <div className="empty-state compact-empty">
          <span className="empty-glyph clear-glyph" aria-hidden="true">✓</span>
          <h3>No risk signals</h3>
          <p>No analyzed mission pairs are currently competing for attention.</p>
        </div>
      ) : (
        <div className="risk-list">
          {risks.map((risk) => (
            <button
              className={`risk-card risk-${risk.level.toLowerCase()} ${selectedRiskId === risk.id ? 'selected' : ''}`}
              key={risk.id}
              type="button"
              onClick={() => onSelectRisk(risk.id)}
              aria-pressed={selectedRiskId === risk.id}
            >
              <span className="risk-card-top">
                <StatusPill status={risk.level} />
                <span>{risk.relations.length} relations</span>
              </span>
              <strong>{risk.title}</strong>
              <span>{risk.summary}</span>
            </button>
          ))}
        </div>
      )}
    </section>
  );
}

import type { MissionStatus, ProviderStatus, RiskLevel, RunnerStatus } from '../domain';

type Status = MissionStatus | ProviderStatus | RiskLevel | RunnerStatus;

const statusLabels: Record<Status, string> = {
  queued: 'Queued',
  active: 'Active',
  blocked: 'Blocked',
  complete: 'Complete',
  online: 'Online',
  degraded: 'Degraded',
  offline: 'Offline',
  idle: 'Idle',
  BLOCK: 'Block',
  REVIEW: 'Review',
  CLEAR: 'Clear',
};

interface StatusPillProps {
  status: Status;
}

export function StatusPill({ status }: StatusPillProps) {
  return <span className={`status-pill status-${status.toLowerCase()}`}>{statusLabels[status]}</span>;
}

import { render, screen } from '@testing-library/react';
import { describe, expect, it } from 'vitest';
import type { DashboardSnapshot, Runner } from '../domain';
import { syntheticDashboardFixture } from '../fixtures/syntheticDashboardFixture';
import { Dashboard } from './Dashboard';

function snapshotWith(overrides: Partial<DashboardSnapshot>): DashboardSnapshot {
  return { ...syntheticDashboardFixture, ...overrides };
}

describe('Dashboard', () => {
  it('renders zero members and zero missions as useful empty states', () => {
    render(<Dashboard snapshot={snapshotWith({ runners: [], missions: [], risks: [] })} />);

    expect(screen.getByText('No runners connected')).toBeInTheDocument();
    expect(screen.getByText('No missions planned')).toBeInTheDocument();
  });

  it('renders one dynamically supplied member', () => {
    const runner: Runner = {
      id: 'solo-runner',
      displayName: 'Solo Signal',
      role: 'Release engineer',
      archetype: 'Night Watch',
      accent: '#44d7b6',
      initials: 'SS',
      status: 'idle',
      provider: 'Codex',
    };

    render(<Dashboard snapshot={snapshotWith({ runners: [runner], missions: [] })} />);

    expect(screen.getByRole('heading', { name: 'Solo Signal' })).toBeInTheDocument();
    expect(screen.getByText('Release engineer')).toBeInTheDocument();
    expect(screen.getByText('Awaiting assignment')).toBeInTheDocument();
  });

  it('renders multiple supplied members and missions without fixed counts', () => {
    render(<Dashboard snapshot={syntheticDashboardFixture} />);

    for (const runner of syntheticDashboardFixture.runners) {
      expect(screen.getByRole('heading', { name: runner.displayName })).toBeInTheDocument();
    }
    for (const mission of syntheticDashboardFixture.missions) {
      expect(screen.getByRole('heading', { name: mission.title })).toBeInTheDocument();
    }
    expect(screen.getByText(`${syntheticDashboardFixture.missions.length} total pathways`)).toBeInTheDocument();
  });

  it('shows blocker evidence, relation types, locations, and recommended targets', () => {
    const blocker = syntheticDashboardFixture.risks.find((risk) => risk.level === 'BLOCK')!;
    render(<Dashboard snapshot={syntheticDashboardFixture} />);

    expect(screen.getAllByText(blocker.title).length).toBeGreaterThan(0);
    expect(screen.getByText(blocker.evidenceNodes[0].location)).toBeInTheDocument();
    expect(screen.getByText(blocker.relations[0].type)).toBeInTheDocument();
    expect(screen.getByText(blocker.recommendation)).toBeInTheDocument();
    expect(screen.getByText(blocker.reviewTargets[0])).toBeInTheDocument();
  });

  it('surfaces provider failure without crashing the dashboard', () => {
    const failingProvider = {
      ...syntheticDashboardFixture.providers[0],
      status: 'offline' as const,
      detail: 'Session provider returned an unavailable response',
    };
    render(<Dashboard snapshot={snapshotWith({ providers: [failingProvider] })} />);

    expect(screen.getByText('Session provider returned an unavailable response')).toBeInTheDocument();
    expect(screen.getByRole('heading', { name: 'Work in motion' })).toBeInTheDocument();
  });

  it('renders stable loading and aggregate error states', () => {
    const { rerender } = render(<Dashboard loading />);
    expect(screen.getByText('Mapping the mission web…')).toBeInTheDocument();

    rerender(<Dashboard error="Graph provider did not respond" />);
    expect(screen.getByRole('alert')).toHaveTextContent('Graph provider did not respond');
  });
});

export type MissionStatus = 'queued' | 'active' | 'blocked' | 'complete';
export type RiskLevel = 'BLOCK' | 'REVIEW' | 'CLEAR';
export type ProviderStatus = 'online' | 'degraded' | 'offline';
export type RunnerStatus = 'active' | 'idle' | 'offline';

export interface Team {
  id: string;
  name: string;
  callSign: string;
  objective: string;
}

export interface Runner {
  id: string;
  displayName: string;
  role: string;
  archetype: string;
  accent: string;
  initials: string;
  status: RunnerStatus;
  provider: string;
  currentMissionId?: string;
}

export interface Mission {
  id: string;
  title: string;
  intent: string;
  ownerId?: string;
  status: MissionStatus;
  targetCount: number;
  updatedAt: string;
  targets: string[];
}

export interface EvidenceNode {
  id: string;
  label: string;
  kind: 'file' | 'symbol' | 'test';
  location: string;
}

export interface EvidenceRelation {
  id: string;
  from: string;
  to: string;
  type: string;
  confidence: number;
  resolution: 'resolved' | 'heuristic' | 'partial';
}

export interface RiskSignal {
  id: string;
  level: RiskLevel;
  title: string;
  summary: string;
  missionIds: string[];
  evidenceNodes: EvidenceNode[];
  relations: EvidenceRelation[];
  recommendation: string;
  reviewTargets: string[];
}

export interface ProviderHealth {
  id: string;
  name: string;
  status: ProviderStatus;
  detail: string;
  latencyMs?: number;
  lastCheckedAt: string;
}

export interface GitActivity {
  id: string;
  actor: string;
  action: string;
  ref: string;
  timestamp: string;
}

export interface GitSnapshot {
  branch: string;
  head: string;
  dirtyFileCount: number;
  ahead: number;
  behind: number;
  activity: GitActivity[];
}

export interface GraphSnapshot {
  nodeCount: number;
  relationCount: number;
  analyzedDepth: number;
  complete: boolean;
  warning?: string;
}

export interface DashboardSnapshot {
  generatedAt: string;
  team: Team;
  runners: Runner[];
  missions: Mission[];
  risks: RiskSignal[];
  providers: ProviderHealth[];
  git: GitSnapshot;
  graph: GraphSnapshot;
}

